/**
 * `open-lyric/internal` — **not** a public API.
 *
 * The wrap-phase reality documented in
 * `research/editor-structure-implemented.md` is that the component barrel
 * transitively contains the whole application, km-KH and the transcript
 * plugin included (`OpenLyricDashboard` → `OpenLyricEditorApplication` →
 * `plugins/default-plugins.ts`). So the two first-party plugin packages are
 * thin wrappers: everything they need at runtime already lives in this
 * bundle, and they import it from here instead of shipping a second copy.
 *
 * That is a correctness requirement, not an optimization. `shared.ts`
 * (`refs`/`state`) and `markup-fragments.ts` (the id counter behind
 * `linkFragmentIds`) are module-global; duplicating them would give the
 * plugins a different `refs` object than the core reads.
 *
 * This subpath disappears once `editor/scripts/shared.ts` is de-globalized
 * and the plugin packages can own their sources outright.
 */

// `shared.ts` — the app's captured element refs.
export { refreshElementRefs } from '../../../editor/scripts/shared.ts';

// The one-copy-per-page id minter + fragment helpers.
export {
  createHtmlFragment,
  linkFragmentIds,
  queryRef,
} from '../../../editor/html/markup-fragments.ts';

// Browser-storage preferences, shared so a standalone editor and the app
// pages agree on word wrap / spellcheck / keyboard settings.
export { EditorPreferencesStore } from '../../../editor/scripts/app/EditorPreferencesStore.ts';

// Real plugin registry data consumed by the plugin packages.
export { olEditorPluginData } from '../../../editor/plugins/km_KH/km_KH_ol_editor.ts';
export { olEditorTranscriptPluginData } from '../../../editor/plugins/transcript/transcript_ol_editor.ts';

// Stylesheet URLs the plugins contribute through the `style` slot. Exported
// from here so both packages point at one emitted asset.
//
// Re-declared as plain `string` constants rather than re-exported straight
// from the `?url` modules: a bare re-export would leave the `*.scss?url`
// specifier in the emitted `.d.ts`, which only resolves for a consumer that
// happens to have Vite's ambient asset declarations.
import kmKhKeyboardCssAssetUrl from '../../../editor/plugins/km_KH/km_KH_keyboard.scss?url';
import transcriptCssAssetUrl from '../../../editor/plugins/transcript/transcript.scss?url';

const kmKhKeyboardCssUrl: string = kmKhKeyboardCssAssetUrl;
const transcriptCssUrl: string = transcriptCssAssetUrl;

export { kmKhKeyboardCssUrl, transcriptCssUrl };
